using System.Diagnostics.CodeAnalysis;

// SonarAnalyzer decides what is generated code by its own rules (attributes, file names, an <auto-generated> header) and
// ignores .editorconfig's generated_code, which already marks Migrations/ for the other analyzers. EF writes an empty
// Down for a migration with nothing to undo, and a merged migration is never edited (CLAUDE.md), so the rule is
// suppressed for the migrations' namespace here instead. SonarCloud skips Migrations/ altogether (PLAN.md 11).
[assembly: SuppressMessage(
    "Major Code Smell",
    "S1186:Methods should not be empty",
    Justification = "EF Core generates an empty Down for a migration with nothing to undo; merged migrations are never edited.",
    Scope = "namespaceanddescendants",
    Target = "~N:SupportDesk.Data.Migrations")]
